        "XQKbqAKqILs3dbvQ": {
          "name": "Dependente de Água",
          "description": "Uma náiade está ligada a uma nascente, lago ou fonte de água de tamanho semelhante. Se ela estiver a mais de 300 pés (90 metros) longe dele por 24 horas ou mais, ela ganha os ajustes fracos até retornar. Ela pode realizar um ritual de 24 horas para se ligar a um novo corpo de água."
        },
        "qd9QFtwsgr9c7yLU": {
          "name": "Cura pela Água",
          "description": "Para cada 10 minutos que uma náiade passa mergulhada em seu corpo de água ligado, ela recupera 7[cura]{7 Pontos de Vida}."
        }
